#!/usr/bin/env node
// Generates src/design-system/icons/generated/skIconData.ts from design/icons/icon-manifest.json.
// Usage:  node scripts/icons/build-icons.mjs          (write)
//         node scripts/icons/build-icons.mjs --check  (fail if the generated file is stale — use in CI)
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';

const root = process.cwd();
const designDir = join(root, 'design');
const manifestPath = join(designDir, 'icons', 'icon-manifest.json');
const outPath = join(root, 'src', 'design-system', 'icons', 'generated', 'skIconData.ts');
const check = process.argv.includes('--check');

const m = JSON.parse(readFileSync(manifestPath, 'utf8'));
const read = (rel) => readFileSync(join(designDir, rel), 'utf8').trim();
const q = (s) => JSON.stringify(s);

// Line / solid icons as data: each element is [tag, attributes]. Drawn at 24×24 with currentColor.
const line = m.icons
  .map((i) => `  ${q(i.name)}: { mode: ${q(i.kind)}, els: ${JSON.stringify(i.elements)} },`)
  .join('\n');

// 3D tiles, small glyphs and the brand mark keep their exact artwork (gradients, highlights), so they ship as SVG markup.
const raw = (list) => list.filter((x) => x.file).map((x) => `  ${q(x.name)}: ${q(read(x.file))},`).join('\n');
const tiles = raw(m.icons3d);
const glyphs = raw(m.other.filter((o) => o.kind === 'glyph' || o.kind === '3d-other'));
const illustrations = raw(m.other.filter((o) => o.kind === 'illustration'));
const brandFile = join(designDir, 'brand', 'studentkare-logo.svg');
const brand = existsSync(brandFile) ? readFileSync(brandFile, 'utf8').trim() : '';

const src = `// GENERATED by scripts/icons/build-icons.mjs from design/icons/icon-manifest.json — do not edit by hand.
/* eslint-disable */
export type SkIconElement = readonly [tag: 'path' | 'circle' | 'rect' | 'line' | 'polyline' | 'polygon' | 'ellipse', attrs: Readonly<Record<string, string>>];
export interface SkIconDef { readonly mode: 'line' | 'solid'; readonly els: readonly SkIconElement[] }

/** ${m.icons.length} line/solid icons, 24 px grid, drawn with currentColor. */
export const skIcons = {
${line}
} as const satisfies Record<string, SkIconDef>;
export type SkIconName = keyof typeof skIcons;

/** ${m.icons3d.length} 3D icon tiles (72 px artwork). */
export const skIcons3d = {
${tiles}
} as const;
export type SkIcon3dName = keyof typeof skIcons3d;

/** Small glyphs and badges that are not on the 24 px grid. */
export const skGlyphs = {
${glyphs}
} as const;
export type SkGlyphName = keyof typeof skGlyphs;

/** Inline SVG illustrations from the canvas (raster images live in design/assets). */
export const skIllustrations = {
${illustrations}
} as const;
export type SkIllustrationName = keyof typeof skIllustrations;

export const skBrandLogo = ${q(brand)};

/** Text symbols in the designs that must be drawn with an icon instead. */
export const skTextGlyphIcons = ${JSON.stringify(Object.fromEntries(Object.entries(m.textGlyphs).filter(([, v]) => v.useIcon).map(([k, v]) => [k, v.useIcon])), null, 2)} as const;
`;

// Animated set (Lottie, built by scripts/icons/build-lottie.mjs). Web loads each file as its own lazy chunk
// with lottie-web; native requires it on first use (Metro evaluates a require when it runs).
const animated = m.animated || [];
const animMeta = (a) => `kind: ${q(a.kind)}, width: ${a.width}, height: ${a.height}, loop: ${a.loop}, rest: ${a.rest}, danger: ${a.danger}`;
const animHeader = (where) => `// GENERATED by scripts/icons/build-icons.mjs from design/icons/icon-manifest.json (animated) — do not edit by hand.
/* eslint-disable */
// ${where}
export type SkAnimatedKind = 'icon' | 'illustration' | 'chart';
export interface SkAnimatedDef {
  readonly kind: SkAnimatedKind;
  /** The comp's size in px (the drawing keeps this aspect ratio). */
  readonly width: number;
  readonly height: number;
  /** Plays as a loop by default (loaders, scenes); otherwise once. */
  readonly loop: boolean;
  /** Progress 0–1 of the still frame shown under reduced motion. */
  readonly rest: number;
  /** May be drawn in a danger colour (errors, SOS). */
  readonly danger: boolean;
  readonly load: () => Promise<unknown>;
}
`;
const animWeb = `${animHeader('Web: each animation is its own chunk, fetched the first time it is shown.')}
/** ${animated.length} animations. */
export const skAnimated = {
${animated.map((a) => `  ${q(a.name)}: { ${animMeta(a)}, load: () => import(${q(`../../../assets/lottie/${a.name}.json`)}).then((mod) => mod.default) },`).join('\n')}
} as const satisfies Record<string, SkAnimatedDef>;
export type SkAnimatedName = keyof typeof skAnimated;
`;
const animNative = `${animHeader('Native: bundled; each file is evaluated the first time it is shown.')}
/** ${animated.length} animations. */
export const skAnimated = {
${animated.map((a) => `  ${q(a.name)}: { ${animMeta(a)}, load: () => Promise.resolve(require(${q(`../../../assets/lottie/${a.name}.json`)})) },`).join('\n')}
} as const satisfies Record<string, SkAnimatedDef>;
export type SkAnimatedName = keyof typeof skAnimated;
`;
const animWebPath = join(root, 'src', 'design-system', 'icons', 'generated', 'skAnimatedData.ts');
const animNativePath = join(root, 'src', 'design-system', 'icons', 'generated', 'skAnimatedData.native.ts');
const outputs = [[outPath, src], [animWebPath, animWeb], [animNativePath, animNative]];

if (check) {
  const stale = outputs.filter(([path, text]) => (existsSync(path) ? readFileSync(path, 'utf8') : '') !== text);
  if (stale.length) {
    console.error(`${stale.map(([p]) => p.split('/').pop()).join(', ')} out of date. Run: node scripts/icons/build-icons.mjs`);
    process.exit(1);
  }
  for (const a of animated) {
    if (!existsSync(join(root, a.file))) { console.error(`Animated ${a.name}: ${a.file} is missing. Run scripts/icons/build-lottie.mjs.`); process.exit(1); }
  }
  console.log('skIconData.ts and skAnimatedData are up to date.');
} else {
  mkdirSync(dirname(outPath), { recursive: true });
  for (const [path, text] of outputs) writeFileSync(path, text);
  console.log(`Wrote ${outPath}: ${m.icons.length} icons, ${m.icons3d.length} 3D tiles, ${glyphs.split('\n').filter(Boolean).length} glyphs; ${animated.length} animations.`);
}
